<?php require __DIR__.'/layout.php';$rows=db()->query("SELECT * FROM people WHERE published=1 AND group_type='COORDENACAO' ORDER BY sort_order,name")->fetchAll();site_header('Coordenação');?>
<main id="conteudo-principal" class="content-page"><header class="page-banner"><span>QUEM FAZ ACONTECER</span><h1>Coordenação</h1><p>Equipe responsável por guiar, organizar e apoiar a Banda Amaral Brasil.</p></header><div class="people-grid"><?php foreach($rows as $p):?><article class="person-card"><?php if($p['photo_path']):?><img src="<?=e($p['photo_path'])?>" alt="<?=e($p['name'])?>"><?php else:?><div class="photo-placeholder">◆</div><?php endif;?><div><h3><?=e($p['name'])?></h3><strong><?=e($p['role'])?></strong><p><?=e($p['biography'])?></p></div></article><?php endforeach;?></div><?php if(!$rows):?><div class="empty-public">A coordenação será cadastrada pelo Admin.</div><?php endif;?></main><?php site_footer();?>